<?php
namespace App\Actions\Order;
use App\Enums\OrderStatus; use App\Models\Order; use App\Services\Audit\AuditService; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class UpdateOrderStatusAction { private array $allowed=['submitted'=>['confirmed','cancelled'],'confirmed'=>['ordering','cancelled'],'ordering'=>['ordered','cancelled'],'ordered'=>['delivering','completed'],'delivering'=>['completed'],'completed'=>[],'cancelled'=>[]]; public function execute(Order $order,string $next): Order { return DB::transaction(function()use($order,$next){$order=Order::whereKey($order->id)->lockForUpdate()->firstOrFail();$current=$order->status->value;if(!in_array($next,$this->allowed[$current]??[],true))throw ValidationException::withMessages(['status'=>'Chuyển trạng thái order không hợp lệ.']);$order->status=OrderStatus::from($next);if($next==='completed')$order->completed_at=now();if($next==='cancelled')$order->cancelled_at=now();$order->save();app(AuditService::class)->record('order.status_updated','order',$order->id,$order->room_id,['status'=>$current],['status'=>$next]);return $order->fresh();}); } }
